         u=[3,5,7,9,11,13,15,17];
         %---------------------------------------------------

         if fengji>8
             fengji=8;
         end
         if fengji<1
             fengji=1;
         end
         fi=fengji;
         wmin=wavewmin(fi);
         wmax=wavewmax(fi);
         wp=wavewp(fi);
         ui=u(fi);
         M=pinpushu;
         N=jiaodushu;
         wavewn=(wmax-wmin)/M;
         thetawn=pi/N;
         dx=1;
         dy=1;
         x=[0:dx:500];
         y=[0:dy:300];
         [x,y]=meshgrid(x,y);
         z=zeros(size(x));
         for wi=1:M
             for ki=1:N
                 theta=-pi/2+(ki-1)*thetawn;
                  epsin=rand*2*pi;
                  w=wmin+(wi-1)*wavewn+wavewn/2;
                  swi=0.81*exp(-7400/(w*ui+eps).^4)*2*(cos(theta)).^2/(pi *(w.^5+eps));
                an=sqrt(2*swi*wavewn*theta);
                z1=w*w*x*cos(theta)/9.8+w*w*y*sin(theta)/9.8+epsin;
                z=an*cos(z1)+z;
             end
         end
         surfl(x,y,abs(z));
         shading flat;
         colormap ;

